// Character-level primitives.
//
// Python strings are sequences of Unicode code points; JavaScript strings are
// sequences of UTF-16 code units. Every place where the original implementation
// indexes into a string or takes its length, we must agree with Python, so all
// such code operates on code-point arrays produced by `toCps`.

/** Split a JS string into an array of one-code-point strings. */
export function toCps(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        out.push(str.slice(i, i + 2));
        i++;
        continue;
      }
    }
    out.push(str[i]);
  }
  return out;
}

/** Number of code points in a string (Python's len()). */
export function cpLen(str) {
  let n = 0;
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

/** Code point of a one-character string (Python's ord()). */
export function ord(ch) {
  return ch.codePointAt(0);
}

/** One-character string for a code point (Python's chr()). */
export function chr(code) {
  return String.fromCodePoint(code);
}

/** True when `ch` is one of the characters in `set` (Python's `ch in "..."`). */
export function inSet(ch, set) {
  return ch.length > 0 && set.indexOf(ch) !== -1 && ch.length === 1
    ? true
    : set.indexOf(ch) !== -1 && ch.length > 1
      ? true
      : set.indexOf(ch) !== -1;
}

/** Compare two single-code-point strings by code point. */
export function cpCompare(a, b) {
  const x = a.codePointAt(0);
  const y = b.codePointAt(0);
  return x < y ? -1 : x > y ? 1 : 0;
}

/** Python's `str.__lt__` — lexicographic comparison by code point. */
export function strCompare(a, b) {
  if (a === b) return 0;
  const ca = toCps(a);
  const cb = toCps(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i++) {
    const c = cpCompare(ca[i], cb[i]);
    if (c !== 0) return c;
  }
  return ca.length < cb.length ? -1 : ca.length > cb.length ? 1 : 0;
}

const DIGITS = '0123456789';
const HEX_DIGITS = '0123456789abcdefABCDEF';
const LETTERS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

export function isDigit(ch) {
  return ch.length === 1 && DIGITS.indexOf(ch) !== -1;
}

export function isHexDigit(ch) {
  return ch.length === 1 && HEX_DIGITS.indexOf(ch) !== -1;
}

export function isAlpha(ch) {
  return ch.length === 1 && (LETTERS.indexOf(ch) !== -1 || DIGITS.indexOf(ch) !== -1 || ch === '-' || ch === '_');
}

/** Zero-pad a non-negative integer to `width` digits. */
export function pad(value, width) {
  let s = String(value);
  while (s.length < width) s = '0' + s;
  return s;
}

/** Uppercase hexadecimal representation of a non-negative integer, zero padded. */
export function hexUpper(value, width) {
  const digits = '0123456789ABCDEF';
  let s = '';
  let v = value;
  if (v === 0) s = '0';
  while (v > 0) {
    s = digits[v % 16] + s;
    v = Math.floor(v / 16);
  }
  while (s.length < width) s = '0' + s;
  return s;
}

/** `count` copies of `str` (Python's `str * count`). */
export function repeat(str, count) {
  let out = '';
  for (let i = 0; i < count; i++) out += str;
  return out;
}

