// Numeric primitives: Python's int/float text formats and exact int/float
// comparison. Python ints are arbitrary precision (BigInt here); Python floats
// are IEEE-754 doubles, same as JS numbers, but the *text* forms differ.

import { pad, repeat } from './chars.mjs';

/** Python's `str(int)`. */
export function intToStr(value) {
  return value.toString();
}

/**
 * Decompose a finite nonzero double into shortest round-trip decimal digits and
 * a decimal point position, so that value == 0.<digits> * 10**decpt.
 */
function shortestDigits(abs) {
  const text = abs.toExponential(); // shortest significand that round-trips
  let mantissa = text;
  let exponent = 0;
  const eAt = text.indexOf('e');
  if (eAt !== -1) {
    mantissa = text.slice(0, eAt);
    exponent = Number(text.slice(eAt + 1));
  }
  let digits = '';
  for (let i = 0; i < mantissa.length; i++) {
    if (mantissa[i] !== '.') digits += mantissa[i];
  }
  // Strip trailing zeros; `toExponential()` should not produce them, but a
  // single "0" digit must survive.
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end--;
  digits = digits.slice(0, end);
  return { digits, decpt: exponent + 1 };
}

/**
 * Python's `repr(float)` — CPython's 'r' format: shortest round-tripping
 * digits, switching to exponential notation when decpt <= -4 or decpt > 16,
 * always keeping a fractional part in fixed notation, and using a signed
 * exponent of at least two digits.
 */
export function floatRepr(value) {
  if (value !== value) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || (value === 0 && 1 / value < 0);
  const abs = negative ? -value : value;
  let body;
  if (abs === 0) {
    body = '0.0';
  } else {
    const { digits, decpt } = shortestDigits(abs);
    if (decpt <= -4 || decpt > 16) {
      const exponent = decpt - 1;
      const sign = exponent < 0 ? '-' : '+';
      const magnitude = exponent < 0 ? -exponent : exponent;
      body = digits[0] + (digits.length > 1 ? '.' + digits.slice(1) : '') + 'e' + sign + pad(magnitude, 2);
    } else if (decpt <= 0) {
      body = '0.' + repeat('0', -decpt) + digits;
    } else if (decpt >= digits.length) {
      body = digits + repeat('0', decpt - digits.length) + '.0';
    } else {
      body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
  }
  return negative ? '-' + body : body;
}

/** True when the string holds only characters Python's float() accepts. */
function isFloatText(text) {
  if (text.length === 0) return false;
  const allowed = '0123456789.eE+-';
  for (let i = 0; i < text.length; i++) {
    if (allowed.indexOf(text[i]) === -1) return false;
  }
  return true;
}

/** Python's `float(str)` for the decimal forms the resolver produces. */
export function parseFloatText(text) {
  if (!isFloatText(text)) {
    const error = new Error('could not convert string to float: ' + text);
    error.pyType = 'ValueError';
    throw error;
  }
  return Number(text);
}

/** Python's `int(str, base)` for base 2, 8, 10 and 16. */
export function parseIntText(text, base) {
  const digits = '0123456789abcdefghijklmnopqrstuvwxyz';
  let result = 0n;
  const bigBase = BigInt(base);
  if (text.length === 0) {
    const error = new Error('invalid literal for int()');
    error.pyType = 'ValueError';
    throw error;
  }
  for (let i = 0; i < text.length; i++) {
    const digit = digits.indexOf(text[i].toLowerCase());
    if (digit === -1 || digit >= base) {
      const error = new Error('invalid literal for int() with base ' + base + ": '" + text + "'");
      error.pyType = 'ValueError';
      throw error;
    }
    result = result * bigBase + BigInt(digit);
  }
  return result;
}

/** Exact BigInt value of a double that is known to be integral and finite. */
export function floatToExactBigInt(value) {
  if (value === 0) return 0n;
  const negative = value < 0;
  const abs = negative ? -value : value;
  const buffer = new ArrayBuffer(8);
  const view = new DataView(buffer);
  view.setFloat64(0, abs);
  const hi = view.getUint32(0);
  const lo = view.getUint32(4);
  const rawExponent = (hi >>> 20) & 0x7ff;
  const mantissa = (BigInt(hi & 0xfffff) << 32n) | BigInt(lo);
  let significand;
  let exponent;
  if (rawExponent === 0) {
    significand = mantissa;
    exponent = -1074;
  } else {
    significand = mantissa | (1n << 52n);
    exponent = rawExponent - 1075;
  }
  let result;
  if (exponent >= 0) result = significand << BigInt(exponent);
  else result = significand >> BigInt(-exponent);
  return negative ? -result : result;
}

/** True when a double holds an exact integer value. */
export function isIntegralFloat(value) {
  return isFinite(value) && Math.floor(value) === value;
}

/** Python's exact `int <=> float` comparison. Returns -1, 0, 1 or NaN (unordered). */
export function compareBigIntFloat(left, right) {
  if (right !== right) return NaN;
  if (right === Infinity) return -1;
  if (right === -Infinity) return 1;
  const truncated = floatToExactBigInt(Math.trunc(right));
  if (left < truncated) return -1;
  if (left > truncated) return 1;
  const fraction = right - Math.trunc(right);
  if (fraction > 0) return -1;
  if (fraction < 0) return 1;
  return 0;
}

