// Python's comparison semantics, and the stable sort that represent_mapping
// relies on. Only `<` is ever used by sorted(), and a comparison between
// incompatible types raises TypeError, which PyYAML catches to leave a mapping
// in its original order.

import { compareBigIntFloat } from './numbers.mjs';
import { strCompare } from './chars.mjs';
import { PyBytes, PyDate, PyDateTime, PyDict, PySet, PyTuple, PyTypeError, hashKey, isHashable, pyTypeName } from './values.mjs';

function isNumber(value) {
  const type = typeof value;
  return type === 'boolean' || type === 'bigint' || type === 'number';
}

function unorderable(left, right) {
  return new PyTypeError(
    "'<' not supported between instances of '" + pyTypeName(left) + "' and '" + pyTypeName(right) + "'"
  );
}

/** Python's `==`. Never raises. */
export function pyEq(left, right) {
  if (left === right) return true;
  if (Array.isArray(left) || Array.isArray(right)) {
    if (!Array.isArray(left) || !Array.isArray(right)) return false;
    if (left.length !== right.length) return false;
    for (let i = 0; i < left.length; i++) {
      if (!pyEq(left[i], right[i])) return false;
    }
    return true;
  }
  if (left instanceof PyDict || right instanceof PyDict) {
    if (!(left instanceof PyDict) || !(right instanceof PyDict)) return false;
    if (left.size !== right.size) return false;
    for (const [key, value] of left.items()) {
      if (!right.hasKey(key)) return false;
      if (!pyEq(right.getItem(key), value)) return false;
    }
    return true;
  }
  if (left instanceof PySet || right instanceof PySet) {
    if (!(left instanceof PySet) || !(right instanceof PySet)) return false;
    if (left.size !== right.size) return false;
    for (const value of left.values()) {
      if (!right.has(value)) return false;
    }
    return true;
  }
  if (!isHashable(left) || !isHashable(right)) return false;
  const leftHash = hashKey(left);
  const rightHash = hashKey(right);
  if (leftHash === null || rightHash === null) return false; // NaN
  return leftHash === rightHash;
}

/** Python's `<`. Raises PyTypeError for values of unorderable types. */
export function pyLt(left, right) {
  if (isNumber(left) && isNumber(right)) {
    const leftBig = typeof left === 'boolean' ? (left ? 1n : 0n) : left;
    const rightBig = typeof right === 'boolean' ? (right ? 1n : 0n) : right;
    const leftIsInt = typeof leftBig === 'bigint';
    const rightIsInt = typeof rightBig === 'bigint';
    if (leftIsInt && rightIsInt) return leftBig < rightBig;
    if (!leftIsInt && !rightIsInt) return leftBig < rightBig;
    if (leftIsInt) {
      const result = compareBigIntFloat(leftBig, rightBig);
      return result === result && result < 0;
    }
    const result = compareBigIntFloat(rightBig, leftBig);
    return result === result && result > 0;
  }
  if (typeof left === 'string' && typeof right === 'string') return strCompare(left, right) < 0;
  if (left instanceof PyBytes && right instanceof PyBytes) {
    const a = left.bytes;
    const b = right.bytes;
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      if (a[i] !== b[i]) return a[i] < b[i];
    }
    return a.length < b.length;
  }
  if (left instanceof PyDateTime && right instanceof PyDateTime) {
    const leftAware = left.tzMinutes !== null;
    const rightAware = right.tzMinutes !== null;
    if (leftAware !== rightAware) {
      throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
    }
    const a = leftAware ? left.utcMicros() : left.naiveMicros();
    const b = rightAware ? right.utcMicros() : right.naiveMicros();
    return a < b;
  }
