export function pySorted(items, lessThan) {
  const compare = lessThan || pyLt;
  if (items.length < 2) return items.slice();
  const merge = list => {
    if (list.length < 2) return list;
    const middle = Math.floor(list.length / 2);
    const left = merge(list.slice(0, middle));
    const right = merge(list.slice(middle));
    const out = [];
    let i = 0;
    let j = 0;
    while (i < left.length && j < right.length) {
      // Take from the right half only on a strict `right < left`, keeping the
      // sort stable.
      if (compare(right[j], left[i])) out.push(right[j++]);
      else out.push(left[i++]);
    }
    while (i < left.length) out.push(left[i++]);
    while (j < right.length) out.push(right[j++]);
    return out;
  };
  return merge(items.slice());
}

/** Sorts (key, value) pairs the way Python sorts a list of 2-tuples. */
export function sortedPairs(pairs) {
  return pySorted(pairs, (a, b) => sequenceLt(a, b));
}

