// A faithful-enough replica of the Python argparse behaviour exercised by
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//     args = parser.parse_args()
//
// Only two option strings exist: the automatic -h/--help and the required --a.
// The subtle parts reproduced here are which argument values are mistaken for
// option strings, prefix abbreviation, and the '--' separator.

