// the executable name, which is the reference behaviour we align to.
const PROG = 'test20_executable';

const USAGE = 'usage: ' + PROG + ' [-h] --a A';

const HELP_TEXT =
  USAGE + '\n' +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

const PREFIX_CHARS = '-';

// argparse's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$
function looksLikeNegativeNumber(text) {
  if (text.length < 2 || text[0] !== '-') return false;
  const digits = '0123456789';
  let index = 1;
  let intDigits = 0;
  while (index < text.length && digits.indexOf(text[index]) !== -1) {
    index++;
    intDigits++;
  }
  if (index === text.length) return intDigits > 0; // -\d+
  if (text[index] !== '.') return false;
  index++;
  let fracDigits = 0;
  while (index < text.length && digits.indexOf(text[index]) !== -1) {
    index++;
    fracDigits++;
  }
  return index === text.length && fracDigits > 0; // -\d*\.\d+
}

const ACTIONS = {
  '-h': 'help',
  '--help': 'help',
  '--a': 'a',
};

