  const result = [];
  const isPrefix = ch => PREFIX_CHARS.indexOf(ch) !== -1;
  if (isPrefix(argString[0]) && argString.length > 1 && isPrefix(argString[1])) {
    let optionPrefix = argString;
    let explicitArg = null;
    const equals = argString.indexOf('=');
    if (equals !== -1) {
      optionPrefix = argString.slice(0, equals);
      explicitArg = argString.slice(equals + 1);
    }
    for (const optionString of Object.keys(ACTIONS)) {
      if (optionString.slice(0, optionPrefix.length) === optionPrefix) {
        result.push({ action: ACTIONS[optionString], optionString, explicitArg });
      }
    }
