    const optionPrefix = argString;
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const optionString of Object.keys(ACTIONS)) {
      if (optionString === shortOptionPrefix) {
        result.push({ action: ACTIONS[optionString], optionString, explicitArg: shortExplicitArg });
      } else if (optionString.slice(0, optionPrefix.length) === optionPrefix) {
        result.push({ action: ACTIONS[optionString], optionString, explicitArg: null });
