  constructor(message) {
    super(message);
    this.yamlClass = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.yamlClass = 'yaml.serializer.SerializerError';
  }
}

