// Token types produced by the scanner (yaml/tokens.py).

class Token {
  constructor(startMark, endMark) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

function simpleToken(id) {
  const cls = class extends Token {};
  cls.prototype.id = id;
  return cls;
}

export const StreamStartToken = class extends Token {
  constructor(startMark, endMark, encoding) {
    super(startMark, endMark);
    this.encoding = encoding === undefined ? null : encoding;
  }
};
StreamStartToken.prototype.id = '<stream start>';

export const StreamEndToken = simpleToken('<stream end>');

export const DirectiveToken = class extends Token {
  constructor(name, value, startMark, endMark) {
    super(startMark, endMark);
    this.name = name;
    this.value = value;
  }
};
DirectiveToken.prototype.id = '<directive>';

export const DocumentStartToken = simpleToken('<document start>');
export const DocumentEndToken = simpleToken('<document end>');
