// The character stream the scanner reads from (yaml/reader.py).
//
// The buffer is a code-point array so that peek/forward/index/column all count
// Unicode code points exactly as Python does.

import { toCps, inSet, ord } from '../py/chars.mjs';
import { LB, BOM } from '../py/charsets.mjs';
import { Mark } from './error.mjs';
import { ReaderError } from './error.mjs';

const PRINTABLE_EXCLUDED_START = 0x10000;

/** Mirrors Reader.NON_PRINTABLE: the set of characters YAML input may not hold. */
function isNonPrintable(code) {
  if (code === 0x09 || code === 0x0a || code === 0x0d) return false;
  if (code >= 0x20 && code <= 0x7e) return false;
  if (code === 0x85) return false;
  if (code >= 0xa0 && code <= 0xd7ff) return false;
  if (code >= 0xe000 && code <= 0xfffd) return false;
  if (code >= PRINTABLE_EXCLUDED_START && code <= 0x10ffff) return false;
  return true;
}

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.encoding = null;
    this.checkPrintable(text);
    // The trailing NUL is the end-of-stream sentinel the scanner tests for.
    this.buffer = toCps(text);
    this.buffer.push('\0');
  }

  checkPrintable(text) {
    const chars = toCps(text);
    for (let i = 0; i < chars.length; i++) {
      const code = ord(chars[i]);
      if (isNonPrintable(code)) {
        throw new ReaderError(
          '<unicode string>', i, chars[i], 'unicode',
          'special characters are not allowed'
        );
      }
    }
  }

  peek(index = 0) {
    const at = this.pointer + index;
    return at < this.buffer.length ? this.buffer[at] : '\0';
  }

  prefix(length = 1) {
    const end = Math.min(this.pointer + length, this.buffer.length);
    return this.buffer.slice(this.pointer, end).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining) {
      const ch = this.buffer[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      const next = this.pointer < this.buffer.length ? this.buffer[this.pointer] : '\0';
      if (inSet(ch, LB) || (ch === '\r' && next !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== BOM) {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

