// The event producer (yaml/parser.py). The grammar states are methods, driven
// by a state variable and an explicit stack, exactly as in the original.

import { ParserError } from './error.mjs';
import { Scanner } from './scanner.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken, BlockMappingStartToken,
  BlockSequenceStartToken, DirectiveToken, DocumentEndToken, DocumentStartToken,
  FlowEntryToken, FlowMappingEndToken, FlowMappingStartToken, FlowSequenceEndToken,
  FlowSequenceStartToken, KeyToken, ScalarToken, StreamEndToken, TagToken, ValueToken,
} from './tokens.mjs';
import {
  AliasEvent, DocumentEndEvent, DocumentStartEvent, MappingEndEvent, MappingStartEvent,
  ScalarEvent, SequenceEndEvent, SequenceStartEvent, StreamEndEvent, StreamStartEvent,
} from './events.mjs';

const DEFAULT_TAGS = new Map([
  ['!', '!'],
  ['!!', 'tag:yaml.org,2002:'],
]);

export class Parser extends Scanner {
  constructor(text) {
    super(text);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = this.parseStreamStart;
  }

  checkEvent(...choices) {
    if (this.currentEvent === null && this.state) this.currentEvent = this.state.call(this);
    if (this.currentEvent !== null) {
      if (choices.length === 0) return true;
      for (const choice of choices) {
        if (this.currentEvent instanceof choice) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state) this.currentEvent = this.state.call(this);
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state) this.currentEvent = this.state.call(this);
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  parseStreamStart() {
    const token = this.getToken();
    this.state = this.parseImplicitDocumentStart;
    return new StreamStartEvent(token.startMark, token.endMark, token.encoding);
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const mark = token.startMark;
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseBlockNode;
      return new DocumentStartEvent(mark, mark, false);
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken(DocumentEndToken)) this.getToken();
    if (!this.checkToken(StreamEndToken)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(DocumentStartToken)) {
        throw new ParserError(
          null, null,
          "expected '<document start>', but found " + pyReprText(this.peekToken().id),
          this.peekToken().startMark
        );
      }
      token = this.getToken();
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseDocumentContent;
      return new DocumentStartEvent(startMark, token.endMark, true, version, tags);
    }
    const token = this.getToken();
    this.state = null;
    return new StreamEndEvent(token.startMark, token.endMark);
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = token.startMark;
    let explicit = false;
    if (this.checkToken(DocumentEndToken)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    this.state = this.parseDocumentStart;
    return new DocumentEndEvent(startMark, endMark, explicit);
  }

  parseDocumentContent() {
    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken, StreamEndToken)) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken(DirectiveToken)) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive', token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(
            null, null,
            'found incompatible YAML document (version 1.* is required)', token.startMark
          );
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(
            null, null, 'duplicate tag handle ' + pyReprText(handle), token.startMark
          );
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    const value = this.tagHandles.size > 0
      ? [this.yamlVersion, new Map(this.tagHandles)]
      : [this.yamlVersion, null];
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return value;
  }

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block, indentlessSequence) {
    if (this.checkToken(AliasToken)) {
      const token = this.getToken();
      this.state = this.states.pop();
      return new AliasEvent(token.value, token.startMark, token.endMark);
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken(AnchorToken)) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken(TagToken)) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken(TagToken)) {
      let token = this.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken(AnchorToken)) {
        token = this.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!this.tagHandles.has(handle)) {
          throw new ParserError(
            'while parsing a node', startMark,
            'found undefined tag handle ' + pyReprText(handle), tagMark
          );
        }
        tag = this.tagHandles.get(handle) + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = this.peekToken().startMark;
      endMark = startMark;
    }
    const implicit = tag === null || tag === '!';
    if (indentlessSequence && this.checkToken(BlockEntryToken)) {
      endMark = this.peekToken().endMark;
      this.state = this.parseIndentlessSequenceEntry;
      return new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
    }
    if (this.checkToken(ScalarToken)) {
      const token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
      else if (tag === null) scalarImplicit = [false, true];
      else scalarImplicit = [false, false];
      this.state = this.states.pop();
      return new ScalarEvent(anchor, tag, scalarImplicit, token.value, startMark, endMark, token.style);
    }
    if (this.checkToken(FlowSequenceStartToken)) {
      endMark = this.peekToken().endMark;
      this.state = this.parseFlowSequenceFirstEntry;
      return new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
    }
    if (this.checkToken(FlowMappingStartToken)) {
      endMark = this.peekToken().endMark;
      this.state = this.parseFlowMappingFirstKey;
      return new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
    }
    if (block && this.checkToken(BlockSequenceStartToken)) {
      endMark = this.peekToken().startMark;
      this.state = this.parseBlockSequenceFirstEntry;
      return new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
    }
    if (block && this.checkToken(BlockMappingStartToken)) {
      endMark = this.peekToken().startMark;
      this.state = this.parseBlockMappingFirstKey;
      return new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
    }
    if (anchor !== null || tag !== null) {
      this.state = this.states.pop();
      return new ScalarEvent(anchor, tag, [implicit, false], '', startMark, endMark);
    }
    const node = block ? 'block' : 'flow';
    const token = this.peekToken();
    throw new ParserError(
      'while parsing a ' + node + ' node', startMark,
      'expected the node content, but found ' + pyReprText(token.id), token.startMark
    );
  }

  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken(BlockEntryToken)) {
      const token = this.getToken();
      if (!this.checkToken(BlockEntryToken, BlockEndToken)) {
        this.states.push(this.parseBlockSequenceEntry);
        return this.parseBlockNode();
      }
      this.state = this.parseBlockSequenceEntry;
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(BlockEndToken)) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block collection', this.marks[this.marks.length - 1],
        'expected <block end>, but found ' + pyReprText(token.id), token.startMark
      );
    }
    const token = this.getToken();
    this.state = this.states.pop();
    this.marks.pop();
    return new SequenceEndEvent(token.startMark, token.endMark);
  }

  parseIndentlessSequenceEntry() {
    if (this.checkToken(BlockEntryToken)) {
      const token = this.getToken();
      if (!this.checkToken(BlockEntryToken, KeyToken, ValueToken, BlockEndToken)) {
        this.states.push(this.parseIndentlessSequenceEntry);
        return this.parseBlockNode();
      }
      this.state = this.parseIndentlessSequenceEntry;
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    this.state = this.states.pop();
    return new SequenceEndEvent(token.startMark, token.startMark);
  }

  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken(KeyToken)) {
      const token = this.getToken();
      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
        this.states.push(this.parseBlockMappingValue);
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = this.parseBlockMappingValue;
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(BlockEndToken)) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block mapping', this.marks[this.marks.length - 1],
        'expected <block end>, but found ' + pyReprText(token.id), token.startMark
      );
    }
    const token = this.getToken();
    this.state = this.states.pop();
    this.marks.pop();
    return new MappingEndEvent(token.startMark, token.endMark);
  }

  parseBlockMappingValue() {
    if (this.checkToken(ValueToken)) {
      const token = this.getToken();
      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
        this.states.push(this.parseBlockMappingKey);
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = this.parseBlockMappingKey;
      return this.processEmptyScalar(token.endMark);
    }
    this.state = this.parseBlockMappingKey;
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first) {
    if (!this.checkToken(FlowSequenceEndToken)) {
      if (!first) {
        if (this.checkToken(FlowEntryToken)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError(
            'while parsing a flow sequence', this.marks[this.marks.length - 1],
            "expected ',' or ']', but got " + pyReprText(token.id), token.startMark
          );
        }
      }
      if (this.checkToken(KeyToken)) {
        const token = this.peekToken();
        this.state = this.parseFlowSequenceEntryMappingKey;
        return new MappingStartEvent(null, null, true, token.startMark, token.endMark, true);
      }
