// Implicit tag resolution (yaml/resolver.py).
//
// PyYAML matches plain scalars against regular expressions. Regular expressions
// are off limits here, so each pattern is transliterated into a hand-written
// matcher over character indices. The matchers are grouped by first character
// and tried in the order PyYAML registers them, because that order decides
// e.g. that '017' is an octal int rather than a timestamp.

import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const BOOL_WORDS = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

const NULL_WORDS = ['~', 'null', 'Null', 'NULL', ''];

function isDigitAt(text, index) {
  return index < text.length && text[index] >= '0' && text[index] <= '9';
}

/** Advance past one or more characters from `set`; returns the new index or -1. */
function takeSome(text, index, set) {
  let at = index;
  while (at < text.length && set.indexOf(text[at]) !== -1) at++;
  return at > index ? at : -1;
}

/** Advance past zero or more characters from `set`. */
function takeAny(text, index, set) {
  let at = index;
  while (at < text.length && set.indexOf(text[at]) !== -1) at++;
  return at;
}

function takeSign(text, index) {
  return index < text.length && (text[index] === '-' || text[index] === '+') ? index + 1 : index;
}

/** (?:[eE][-+][0-9]+) — note the sign is mandatory in PyYAML's float pattern. */
function takeExponent(text, index) {
  if (index >= text.length) return index;
  if (text[index] !== 'e' && text[index] !== 'E') return index;
  let at = index + 1;
  if (at >= text.length || (text[at] !== '-' && text[at] !== '+')) return index;
  at += 1;
  const digits = takeSome(text, at, '0123456789');
  return digits === -1 ? index : digits;
}

/** (?::[0-5]?[0-9])+ — sexagesimal groups. */
function takeSexagesimal(text, index) {
  let at = index;
  let groups = 0;
  for (;;) {
    if (at >= text.length || text[at] !== ':') break;
    let cursor = at + 1;
    if (cursor < text.length && text[cursor] >= '0' && text[cursor] <= '5' && isDigitAt(text, cursor + 1)) {
      cursor += 2;
    } else if (isDigitAt(text, cursor)) {
      cursor += 1;
    } else {
      break;
    }
    at = cursor;
    groups += 1;
  }
  return groups > 0 ? at : -1;
}

function matchBool(value) {
  return BOOL_WORDS.indexOf(value) !== -1;
}

function matchNull(value) {
  return NULL_WORDS.indexOf(value) !== -1;
}

function matchMerge(value) {
  return value === '<<';
}

function matchValueTag(value) {
  return value === '=';
}

function matchYaml(value) {
  return value === '!' || value === '&' || value === '*';
}

/**
 * float:  [-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?
 *       | \.[0-9_]+(?:[eE][-+][0-9]+)?
 *       | [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
 *       | [-+]?\.(?:inf|Inf|INF)
 *       | \.(?:nan|NaN|NAN)
 */
function matchFloat(value) {
  // .inf / .nan forms
  {
    const at = takeSign(value, 0);
    if (value.slice(at) === '.inf' || value.slice(at) === '.Inf' || value.slice(at) === '.INF') return true;
  }
  if (value === '.nan' || value === '.NaN' || value === '.NAN') return true;

  // \.[0-9_]+(?:[eE][-+][0-9]+)?
  if (value.length > 1 && value[0] === '.') {
    const digits = takeSome(value, 1, '0123456789_');
    if (digits !== -1 && takeExponent(value, digits) === value.length) return true;
  }

  const start = takeSign(value, 0);
  if (isDigitAt(value, start)) {
    const intPart = takeAny(value, start + 1, '0123456789_');
    // ...\.[0-9_]*(?:[eE][-+][0-9]+)?
    if (intPart < value.length && value[intPart] === '.') {
