    if (this.checkEvent(AliasEvent)) {
      const event = this.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(
          null, null, "found undefined alias '" + anchor + "'", event.startMark
        );
      }
      return this.anchors.get(anchor);
    }
    const event = this.peekEvent();
    const anchor = event.anchor;
    if (anchor !== null && this.anchors.has(anchor)) {
      throw new ComposerError(
        "found duplicate anchor '" + anchor + "'; first occurrence",
        this.anchors.get(anchor).startMark, 'second occurrence', event.startMark
      );
    }
    this.descendResolver(parent, index);
    let node = null;
    if (this.checkEvent(ScalarEvent)) node = this.composeScalarNode(anchor);
    else if (this.checkEvent(SequenceStartEvent)) node = this.composeSequenceNode(anchor);
    else if (this.checkEvent(MappingStartEvent)) node = this.composeMappingNode(anchor);
    this.ascendResolver();
    return node;
  }

  composeScalarNode(anchor) {
    const event = this.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') tag = this.resolve(ScalarNode, event.value, event.implicit);
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark, event.style);
    if (anchor !== null) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') tag = this.resolve(SequenceNode, null, startEvent.implicit);
    const node = new SequenceNode(tag, [], startEvent.startMark, null, startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.checkEvent(SequenceEndEvent)) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') tag = this.resolve(MappingNode, null, startEvent.implicit);
    const node = new MappingNode(tag, [], startEvent.startMark, null, startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    while (!this.checkEvent(MappingEndEvent)) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

