// base64 in the exact dialect Python's base64 module provides:
//   - decodebytes -> binascii.a2b_base64 in non-strict mode: characters outside
//     the alphabet are skipped, but padding must be correct.
//   - encodebytes -> 76 characters per line, every line terminated by '\n'.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

const REVERSE = new Map();
for (let i = 0; i < ALPHABET.length; i++) REVERSE.set(ALPHABET[i], i);

export class BinasciiError extends Error {
  constructor(message) {
    super(message);
    this.pyType = 'binascii.Error';
  }
}

export function decodeBase64(text) {
  const out = [];
  let quadPos = 0;
  let leftChar = 0;
  let pads = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '=') {
      pads += 1;
      if (quadPos >= 2 && quadPos + pads >= 4) {
        pads = 0;
        quadPos = 0;
        leftChar = 0;
      }
      continue;
    }
    const value = REVERSE.get(ch);
    if (value === undefined) continue;
    pads = 0;
    switch (quadPos) {
      case 0:
        quadPos = 1;
        leftChar = value;
        break;
      case 1:
        quadPos = 2;
        out.push(((leftChar << 2) | (value >> 4)) & 0xff);
        leftChar = value & 0x0f;
        break;
      case 2:
        quadPos = 3;
        out.push(((leftChar << 4) | (value >> 2)) & 0xff);
        leftChar = value & 0x03;
        break;
      default:
        quadPos = 0;
        out.push(((leftChar << 6) | value) & 0xff);
        leftChar = 0;
        break;
    }
  }
  if (quadPos !== 0) {
    if (quadPos === 1) {
      throw new BinasciiError(
        'Invalid base64-encoded string: number of data characters (' + out.length +
        ') cannot be 1 more than a multiple of 4'
      );
    }
    throw new BinasciiError('Incorrect padding');
  }
  return new Uint8Array(out);
}

/** Python's base64.encodebytes: wrapped at 76 characters, trailing newline. */
export function encodeBase64Lines(bytes) {
  let body = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const remaining = bytes.length - i;
    const b0 = bytes[i];
    const b1 = remaining > 1 ? bytes[i + 1] : 0;
    const b2 = remaining > 2 ? bytes[i + 2] : 0;
    body += ALPHABET[b0 >> 2];
    body += ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    body += remaining > 1 ? ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    body += remaining > 2 ? ALPHABET[b2 & 0x3f] : '=';
  }
  let out = '';
  for (let i = 0; i < body.length; i += 76) {
    out += body.slice(i, i + 76) + '\n';
  }
  return out;
}

