// Turns the representation graph into Python objects (yaml/constructor.py,
// SafeConstructor). Two-phase constructors are real JS generators, matching
// PyYAML's use of Python generators to support recursive structures.

import { ConstructorError } from './error.mjs';
import { Composer } from './composer.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';
import { decodeBase64 } from '../py/base64.mjs';
import { parseFloatText, parseIntText } from '../py/numbers.mjs';
import {
  PyBytes, PyDate, PyDateTime, PyDict, PySet, PyTuple, isHashable,
} from '../py/values.mjs';
import { cpLen, toCps, ord } from '../py/chars.mjs';

const BOOL_VALUES = new Map([
  ['yes', true],
  ['no', false],
  ['true', true],
  ['false', false],
  ['on', true],
  ['off', false],
]);

const TAG = {
  null: 'tag:yaml.org,2002:null',
  bool: 'tag:yaml.org,2002:bool',
  int: 'tag:yaml.org,2002:int',
  float: 'tag:yaml.org,2002:float',
  binary: 'tag:yaml.org,2002:binary',
  timestamp: 'tag:yaml.org,2002:timestamp',
  omap: 'tag:yaml.org,2002:omap',
  pairs: 'tag:yaml.org,2002:pairs',
  set: 'tag:yaml.org,2002:set',
  str: 'tag:yaml.org,2002:str',
  seq: 'tag:yaml.org,2002:seq',
  map: 'tag:yaml.org,2002:map',
  merge: 'tag:yaml.org,2002:merge',
  value: 'tag:yaml.org,2002:value',
};

function isGenerator(value) {
  return value !== null && typeof value === 'object' && typeof value.next === 'function' &&
    typeof value[Symbol.iterator] === 'function';
}

export class SafeConstructor extends Composer {
  constructor(text) {
    super(text);
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  getSingleData() {
    const node = this.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return null;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) {
        for (const dummy of generator) void dummy;
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null, 'found unconstructable recursive node', node.startMark);
    }
    this.recursiveObjects.set(node, null);
    const constructor = CONSTRUCTORS.get(node.tag);
    let data;
    if (constructor !== undefined) {
      data = constructor.call(this, node);
    } else {
      data = this.constructUndefined(node);
    }
    if (isGenerator(data)) {
      const generator = data;
      data = generator.next().value;
      if (this.deepConstruct) {
        for (const dummy of generator) void dummy;
      } else {
        this.stateGenerators.push(generator);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  constructScalar(node) {
    if (node instanceof MappingNode) {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === TAG.value) return this.constructScalar(valueNode);
      }
    }
    if (!(node instanceof ScalarNode)) {
      throw new ConstructorError(
        null, null, 'expected a scalar node, but found ' + node.id, node.startMark
      );
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        null, null, 'expected a sequence node, but found ' + node.id, node.startMark
      );
    }
    return node.value.map(child => this.constructObject(child, deep));
  }

  flattenMapping(node) {
    const merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === TAG.merge) {
        node.value.splice(index, 1);
        if (valueNode instanceof MappingNode) {
          this.flattenMapping(valueNode);
          for (const item of valueNode.value) merge.push(item);
        } else if (valueNode instanceof SequenceNode) {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (!(subnode instanceof MappingNode)) {
              throw new ConstructorError(
                'while constructing a mapping', node.startMark,
                'expected a mapping for merging, but found ' + subnode.id, subnode.startMark
              );
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) {
            for (const item of value) merge.push(item);
          }
        } else {
          throw new ConstructorError(
            'while constructing a mapping', node.startMark,
            'expected a mapping or list of mappings for merging, but found ' + valueNode.id,
            valueNode.startMark
          );
        }
      } else if (keyNode.tag === TAG.value) {
        keyNode.tag = TAG.str;
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) node.value = merge.concat(node.value);
  }

  constructMapping(node, deep = false) {
    if (node instanceof MappingNode) this.flattenMapping(node);
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null, null, 'expected a mapping node, but found ' + node.id, node.startMark
      );
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      if (!isHashable(key)) {
        throw new ConstructorError(
          'while constructing a mapping', node.startMark, 'found unhashable key', keyNode.startMark
        );
      }
      const value = this.constructObject(valueNode, deep);
      mapping.setItem(key, value);
    }
    return mapping;
  }

  constructPairs(node, deep = false) {
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null, null, 'expected a mapping node, but found ' + node.id, node.startMark
      );
    }
    const pairs = [];
    for (const [keyNode, valueNode] of node.value) {
      pairs.push([this.constructObject(keyNode, deep), this.constructObject(valueNode, deep)]);
    }
    return pairs;
  }

  // -- tag constructors -----------------------------------------------------

  constructYamlNull(node) {
    this.constructScalar(node);
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES.get(value.toLowerCase());
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).split('_').join('');
    let sign = 1n;
    if (value[0] === '-') sign = -1n;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.slice(0, 2) === '0b') return sign * parseIntText(value.slice(2), 2);
    if (value.slice(0, 2) === '0x') return sign * parseIntText(value.slice(2), 16);
    if (value[0] === '0') return sign * parseIntText(value, 8);
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map(part => parseIntText(part, 10));
      digits.reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * parseIntText(value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).split('_').join('').toLowerCase();
    let sign = 1;
    if (value[0] === '-') sign = -1;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '.inf') return sign * Infinity;
    if (value === '.nan') return NaN;
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map(part => parseFloatText(part));
      digits.reverse();
      let base = 1;
      let total = 0.0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return sign * total;
    }
    return sign * parseFloatText(value);
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of toCps(value)) {
      if (ord(ch) > 0x7f) {
        throw new ConstructorError(
          null, null, 'failed to convert base64 data into ascii', node.startMark
        );
      }
    }
    try {
      return new PyBytes(decodeBase64(value));
    } catch (error) {
      throw new ConstructorError(
        null, null, 'failed to decode base64 data: ' + error.message, node.startMark
      );
    }
  }

  constructYamlTimestamp(node) {
    const value = this.constructScalar(node);
    const parsed = parseTimestamp(value);
    if (parsed === null) {
      throw new ConstructorError(null, null, 'could not parse timestamp', node.startMark);
    }
    if (parsed.hour === null) return new PyDate(parsed.year, parsed.month, parsed.day);
    return new PyDateTime(
      parsed.year, parsed.month, parsed.day,
      parsed.hour, parsed.minute, parsed.second, parsed.microsecond, parsed.tzMinutes
    );
  }

  *constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        'while constructing an ordered map', node.startMark,
        'expected a sequence, but found ' + node.id, node.startMark
      );
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError(
          'while constructing an ordered map', node.startMark,
          'expected a mapping of length 1, but found ' + subnode.id, subnode.startMark
        );
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(
          'while constructing an ordered map', node.startMark,
          'expected a single mapping item, but found ' + subnode.value.length + ' items',
          subnode.startMark
        );
      }
      const [keyNode, valueNode] = subnode.value[0];
      omap.push(new PyTuple([this.constructObject(keyNode), this.constructObject(valueNode)]));
    }
  }

  *constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        'while constructing pairs', node.startMark,
        'expected a sequence, but found ' + node.id, node.startMark
      );
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError(
          'while constructing pairs', node.startMark,
          'expected a mapping of length 1, but found ' + subnode.id, subnode.startMark
        );
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(
          'while constructing pairs', node.startMark,
          'expected a single mapping item, but found ' + subnode.value.length + ' items',
          subnode.startMark
        );
      }
      const [keyNode, valueNode] = subnode.value[0];
      pairs.push(new PyTuple([this.constructObject(keyNode), this.constructObject(valueNode)]));
    }
  }

  *constructYamlSet(node) {
    const data = new PySet();
    yield data;
    const value = this.constructMapping(node);
    for (const key of value.keys()) data.add(key);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  *constructYamlSeq(node) {
    const data = [];
    yield data;
    for (const item of this.constructSequence(node)) data.push(item);
  }

  *constructYamlMap(node) {
    const data = new PyDict();
    yield data;
    const value = this.constructMapping(node);
    for (const [key, item] of value.items()) data.setItem(key, item);
  }

  constructUndefined(node) {
    throw new ConstructorError(
      null, null, "could not determine a constructor for the tag '" + node.tag + "'",
      node.startMark
    );
  }
}

const CONSTRUCTORS = new Map([
  [TAG.null, SafeConstructor.prototype.constructYamlNull],
  [TAG.bool, SafeConstructor.prototype.constructYamlBool],
  [TAG.int, SafeConstructor.prototype.constructYamlInt],
  [TAG.float, SafeConstructor.prototype.constructYamlFloat],
  [TAG.binary, SafeConstructor.prototype.constructYamlBinary],
  [TAG.timestamp, SafeConstructor.prototype.constructYamlTimestamp],
  [TAG.omap, SafeConstructor.prototype.constructYamlOmap],
  [TAG.pairs, SafeConstructor.prototype.constructYamlPairs],
  [TAG.set, SafeConstructor.prototype.constructYamlSet],
  [TAG.str, SafeConstructor.prototype.constructYamlStr],
  [TAG.seq, SafeConstructor.prototype.constructYamlSeq],
  [TAG.map, SafeConstructor.prototype.constructYamlMap],
]);

/**
 * PyYAML's timestamp pattern, transliterated:
 *   (\d{4})-(\d{1,2})-(\d{1,2})
 *   (?:(?:[Tt]|[ \t]+)(\d{1,2}):(\d{2}):(\d{2})(?:\.(\d*))?
 *      (?:[ \t]*(Z|([-+])(\d{1,2})(?::(\d{2}))?))?)?
 */
export function parseTimestamp(text) {
  let at = 0;
  const digits = (count, most) => {
    let taken = '';
    while (at < text.length && text[at] >= '0' && text[at] <= '9' && taken.length < most) {
      taken += text[at];
      at++;
    }
    return taken.length >= count ? taken : null;
  };
  const year = digits(4, 4);
  if (year === null || text[at] !== '-') return null;
  at++;
  const month = digits(1, 2);
  if (month === null || text[at] !== '-') return null;
  at++;
  const day = digits(1, 2);
  if (day === null) return null;
  const result = {
    year: Number(year), month: Number(month), day: Number(day),
    hour: null, minute: 0, second: 0, microsecond: 0, tzMinutes: null,
  };
  if (at === text.length) return result;
  if (text[at] === 'T' || text[at] === 't') {
    at++;
  } else if (text[at] === ' ' || text[at] === '\t') {
    while (at < text.length && (text[at] === ' ' || text[at] === '\t')) at++;
  } else {
    return null;
  }
  const hour = digits(1, 2);
  if (hour === null || text[at] !== ':') return null;
  at++;
  const minute = digits(2, 2);
  if (minute === null || text[at] !== ':') return null;
  at++;
  const second = digits(2, 2);
  if (second === null) return null;
  result.hour = Number(hour);
  result.minute = Number(minute);
  result.second = Number(second);
  if (at < text.length && text[at] === '.') {
    at++;
    let fraction = '';
    while (at < text.length && text[at] >= '0' && text[at] <= '9') {
      fraction += text[at];
      at++;
    }
    if (fraction.length > 0) {
      let truncated = fraction.slice(0, 6);
      while (truncated.length < 6) truncated += '0';
      result.microsecond = Number(truncated);
    }
  }
  while (at < text.length && (text[at] === ' ' || text[at] === '\t')) at++;
  if (at === text.length) return result;
  if (text[at] === 'Z') {
    result.tzMinutes = 0;
    return at + 1 === text.length ? result : null;
  }
  const negative = text[at] === '-';
  if (!negative && text[at] !== '+') return null;
  at++;
  const tzHour = digits(1, 2);
  if (tzHour === null) return null;
  let tzMinute = '0';
  if (at < text.length && text[at] === ':') {
    at++;
    tzMinute = digits(2, 2);
    if (tzMinute === null) return null;
  }
  if (at !== text.length) return null;
  const offset = Number(tzHour) * 60 + Number(tzMinute);
  result.tzMinutes = negative ? -offset : offset;
  return result;
}

export { TAG, cpLen };

