// The YAML writer (yaml/emitter.py).
//
// Everything about the output shape lives here: which scalar style is chosen,
// where long scalars fold, and how block collections are indented. All scalar
// text is handled as code-point arrays so that column counting and slicing
// agree with Python for non-BMP characters.

import { cpLen, hexUpper, inSet, ord, repeat, toCps } from '../py/chars.mjs';
import { LB, NEL, NBSP, LS, PS, BOM } from '../py/charsets.mjs';
import { EmitterError } from './error.mjs';
import {
  AliasEvent, CollectionEndEvent, CollectionStartEvent, DocumentEndEvent, DocumentStartEvent,
  MappingEndEvent, MappingStartEvent, NodeEvent, ScalarEvent, SequenceEndEvent,
  SequenceStartEvent, StreamEndEvent, StreamStartEvent,
} from './events.mjs';

const DEFAULT_TAG_PREFIXES = new Map([
  ['!', '!'],
  ['tag:yaml.org,2002:', '!!'],
]);

// Characters that get a named escape inside a double-quoted scalar.
const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'],
  ['\x07', 'a'],
  ['\x08', 'b'],
  ['\t', 't'],
  ['\n', 'n'],
  ['\x0b', 'v'],
  ['\x0c', 'f'],
  ['\r', 'r'],
  ['\x1b', 'e'],
  ['"', '"'],
  ['\\', '\\'],
  [NEL, 'N'],
  [NBSP, '_'],
  [LS, 'L'],
  [PS, 'P'],
]);

const NULL_SPACE_TAB_CR_LB = '\0 \t\r' + LB;
const SPACE_LB = ' ' + LB;
const TAG_URI_SAFE = "-;/?:@&=+$,_.~*'()[]";

class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
              allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

export class Emitter {
  constructor(options = {}) {
    this.chunks = [];
    this.encoding = null;
    this.states = [];
    this.state = this.expectStreamStart;
    this.events = [];
    this.event = null;
    this.indents = [];
    this.indent = null;
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.canonical = options.canonical || false;
    this.allowUnicode = options.allowUnicode || false;
    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) this.bestIndent = options.indent;
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) this.bestWidth = options.width;
    this.bestLineBreak = '\n';
    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  getValue() {
    return this.chunks.join('');
  }

  write(data) {
    this.chunks.push(data);
  }

  // -- event dispatch -------------------------------------------------------

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this.state.call(this);
      this.event = null;
    }
  }

  needMoreEvents() {
    if (this.events.length === 0) return true;
    const event = this.events[0];
    if (event instanceof DocumentStartEvent) return this.needEvents(1);
    if (event instanceof SequenceStartEvent) return this.needEvents(2);
    if (event instanceof MappingStartEvent) return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (let i = 1; i < this.events.length; i++) {
      const event = this.events[i];
      if (event instanceof DocumentStartEvent || event instanceof CollectionStartEvent) level += 1;
      else if (event instanceof DocumentEndEvent || event instanceof CollectionEndEvent) level -= 1;
      else if (event instanceof StreamEndEvent) level = -1;
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // -- states ---------------------------------------------------------------

  expectStreamStart() {
    if (this.event instanceof StreamStartEvent) {
      this.state = this.expectFirstDocumentStart;
    } else {
      throw new EmitterError('expected StreamStartEvent, but got another event');
    }
  }

  expectNothing() {
    throw new EmitterError('expected nothing, but got another event');
  }

  expectFirstDocumentStart() {
    return this.expectDocumentStart(true);
  }

  expectDocumentStartContinue() {
    return this.expectDocumentStart(false);
  }

  expectDocumentStart(first) {
    if (this.event instanceof DocumentStartEvent) {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      if (this.event.version) {
        this.writeVersionDirective(this.prepareVersion(this.event.version));
      }
      this.tagPrefixes = new Map(DEFAULT_TAG_PREFIXES);
      if (this.event.tags) {
        const handles = Array.from(this.event.tags.keys()).sort();
        for (const handle of handles) {
          const prefix = this.event.tags.get(handle);
          this.tagPrefixes.set(prefix, handle);
          this.writeTagDirective(this.prepareTagHandle(handle), this.prepareTagPrefix(prefix));
        }
      }
      const implicit = first && !this.event.explicit && !this.canonical &&
        !this.event.version && !this.event.tags && !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = this.expectDocumentRoot;
    } else if (this.event instanceof StreamEndEvent) {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = this.expectNothing;
    } else {
      throw new EmitterError('expected DocumentStartEvent, but got another event');
    }
  }

  expectDocumentEnd() {
    if (this.event instanceof DocumentEndEvent) {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = this.expectDocumentStartContinue;
    } else {
      throw new EmitterError('expected DocumentEndEvent, but got another event');
    }
  }

  expectDocumentRoot() {
    this.states.push(this.expectDocumentEnd);
    this.expectNode(true, false, false, false);
  }

  expectNode(root, sequence, mapping, simpleKey) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event instanceof AliasEvent) {
      this.expectAlias();
    } else if (this.event instanceof ScalarEvent || this.event instanceof CollectionStartEvent) {
      this.processAnchor('&');
      this.processTag();
      if (this.event instanceof ScalarEvent) {
        this.expectScalar();
      } else if (this.event instanceof SequenceStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle || this.checkEmptySequence()) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else if (this.event instanceof MappingStartEvent) {
        if (this.flowLevel || this.canonical || this.event.flowStyle || this.checkEmptyMapping()) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError('expected NodeEvent, but got another event');
    }
  }

  expectAlias() {
    if (this.event.anchor === null) throw new EmitterError('anchor is not specified for alias');
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true, false);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  expectFlowSequence() {
    this.writeIndicator('[', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = this.expectFirstFlowSequenceItem;
  }

  expectFirstFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push(this.expectFlowSequenceItem);
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push(this.expectFlowSequenceItem);
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowMapping() {
    this.writeIndicator('{', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    this.state = this.expectFirstFlowMappingKey;
  }

  expectFirstFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push(this.expectFlowMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push(this.expectFlowMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push(this.expectFlowMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push(this.expectFlowMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push(this.expectFlowMappingKey);
    this.expectNode(false, false, true, false);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true);
    this.states.push(this.expectFlowMappingKey);
    this.expectNode(false, false, true, false);
  }

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = this.expectFirstBlockSequenceItem;
  }

  expectFirstBlockSequenceItem() {
    return this.expectBlockSequenceItem(true);
  }

  expectBlockSequenceItemContinue() {
    return this.expectBlockSequenceItem(false);
  }

  expectBlockSequenceItem(first) {
    if (!first && this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push(this.expectBlockSequenceItemContinue);
      this.expectNode(false, true, false, false);
    }
  }

  expectBlockMapping() {
    this.increaseIndent(false, false);
    this.state = this.expectFirstBlockMappingKey;
  }

  expectFirstBlockMappingKey() {
    return this.expectBlockMappingKey(true);
  }

  expectBlockMappingKeyContinue() {
    return this.expectBlockMappingKey(false);
  }

  expectBlockMappingKey(first) {
    if (!first && this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push(this.expectBlockMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push(this.expectBlockMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push(this.expectBlockMappingKeyContinue);
    this.expectNode(false, false, true, false);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push(this.expectBlockMappingKeyContinue);
    this.expectNode(false, false, true, false);
  }

  // -- checkers -------------------------------------------------------------

  checkEmptySequence() {
    return this.event instanceof SequenceStartEvent && this.events.length > 0 &&
      this.events[0] instanceof SequenceEndEvent;
  }

  checkEmptyMapping() {
    return this.event instanceof MappingStartEvent && this.events.length > 0 &&
      this.events[0] instanceof MappingEndEvent;
  }

  checkEmptyDocument() {
    if (!(this.event instanceof DocumentStartEvent) || this.events.length === 0) return false;
    const event = this.events[0];
    return event instanceof ScalarEvent && event.anchor === null && event.tag === null &&
      Boolean(event.implicit) && event.value === '';
  }

  checkSimpleKey() {
    let length = 0;
    if (this.event instanceof NodeEvent && this.event.anchor !== null) {
      if (this.preparedAnchor === null) this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      length += cpLen(this.preparedAnchor);
    }
    if ((this.event instanceof ScalarEvent || this.event instanceof CollectionStartEvent) &&
        this.event.tag !== null) {
      if (this.preparedTag === null) this.preparedTag = this.prepareTag(this.event.tag);
      length += cpLen(this.preparedTag);
    }
    if (this.event instanceof ScalarEvent) {
      if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
      length += cpLen(this.analysis.scalar);
    }
    return length < 128 && (
      this.event instanceof AliasEvent ||
      (this.event instanceof ScalarEvent && !this.analysis.empty && !this.analysis.multiline) ||
      this.checkEmptySequence() || this.checkEmptyMapping()
    );
  }

  // -- anchor, tag and scalar processing ------------------------------------

  processAnchor(indicator) {
    if (this.event.anchor === null) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    if (this.preparedAnchor) this.writeIndicator(indicator + this.preparedAnchor, true);
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event instanceof ScalarEvent) {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if ((!this.canonical || tag === null) &&
          ((this.style === '' && this.event.implicit[0]) ||
           (this.style !== '' && this.event.implicit[1]))) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) this.writeIndicator(this.preparedTag, true);
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline)) &&
          ((this.flowLevel && this.analysis.allowFlowPlain) ||
           (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (this.event.style && (this.event.style === '|' || this.event.style === '>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (this.analysis.allowSingleQuoted && !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    const text = toCps(this.analysis.scalar);
    if (this.style === '"') this.writeDoubleQuoted(text, split);
    else if (this.style === "'") this.writeSingleQuoted(text, split);
    else if (this.style === '>') this.writeFolded(text);
    else if (this.style === '|') this.writeLiteral(text);
    else this.writePlain(text, split);
    this.analysis = null;
    this.style = null;
  }

  // -- preparers ------------------------------------------------------------

  prepareVersion(version) {
    const [major, minor] = version;
    if (major !== 1) throw new EmitterError('unsupported YAML version: ' + major + '.' + minor);
    return major + '.' + minor;
  }

  prepareTagHandle(handle) {
    if (!handle) throw new EmitterError('tag handle must not be empty');
    if (handle[0] !== '!' || handle[handle.length - 1] !== '!') {
      throw new EmitterError("tag handle must start and end with '!': " + handle);
    }
    for (const ch of toCps(handle.slice(1, -1))) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
            ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character in the tag handle: ' + handle);
      }
    }
    return handle;
  }

  prepareTagPrefix(prefix) {
    if (!prefix) throw new EmitterError('tag prefix must not be empty');
    const chars = toCps(prefix);
    const chunks = [];
    let start = 0;
    let end = chars[0] === '!' ? 1 : 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
          inSet(ch, TAG_URI_SAFE + '!')) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        for (const byte of utf8Bytes(ch)) chunks.push('%' + hexUpper(byte, 2));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    return chunks.join('');
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Array.from(this.tagPrefixes.keys()).sort();
    for (const prefix of prefixes) {
      if (tag.slice(0, prefix.length) === prefix && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes.get(prefix);
        suffix = tag.slice(prefix.length);
      }
    }
    const chars = toCps(suffix);
    const chunks = [];
    let start = 0;
    let end = 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
          inSet(ch, TAG_URI_SAFE) || (ch === '!' && handle !== '!')) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        for (const byte of utf8Bytes(ch)) chunks.push('%' + hexUpper(byte, 2));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    return handle ? handle + suffixText : '!<' + suffixText + '>';
  }

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of toCps(anchor)) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
            ch === '-' || ch === '_')) {
        throw new EmitterError('invalid character in the anchor: ' + anchor);
      }
    }
    return anchor;
  }

  // -- scalar analysis ------------------------------------------------------

  analyzeScalar(scalar) {
    if (scalar === '') {
      return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
    }
    const chars = toCps(scalar);
    const length = chars.length;

    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;

    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    if (scalar.slice(0, 3) === '---' || scalar.slice(0, 3) === '...') {
      blockIndicators = true;
      flowIndicators = true;
    }

    let precededByWhitespace = true;
    let followedByWhitespace = length === 1 || inSet(chars[1], NULL_SPACE_TAB_CR_LB);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < length) {
      const ch = chars[index];

      if (index === 0) {
        if (inSet(ch, '#,[]{}&*!|>\'"%@`')) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (ch === '?' || ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (inSet(ch, ',?[]{}')) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (inSet(ch, LB)) lineBreaks = true;
      if (!(ch === '\n' || (ch >= '\x20' && ch <= '\x7e'))) {
        const code = ord(ch);
        if ((code === 0x85 || (code >= 0xa0 && code <= 0xd7ff) ||
             (code >= 0xe000 && code <= 0xfffd) ||
             (code >= 0x10000 && code < 0x10ffff)) && ch !== BOM) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === length - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (inSet(ch, LB)) {
        if (index === 0) leadingBreak = true;
        if (index === length - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      index += 1;
      precededByWhitespace = inSet(ch, NULL_SPACE_TAB_CR_LB);
      followedByWhitespace = index + 1 >= length || inSet(chars[index + 1], NULL_SPACE_TAB_CR_LB);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis(
      scalar, false, lineBreaks,
      allowFlowPlain, allowBlockPlain, allowSingleQuoted, allowDoubleQuoted, allowBlock
    );
  }

  // -- writers --------------------------------------------------------------

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    const data = this.whitespace || !needWhitespace ? indicator : ' ' + indicator;
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += cpLen(data);
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent ||
        (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      const data = repeat(' ', indent - this.column);
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data) {
    const text = data === undefined || data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeVersionDirective(versionText) {
    this.write('%YAML ' + versionText);
    this.writeLineBreak();
  }

  writeTagDirective(handleText, prefixText) {
    this.write('%TAG ' + handleText + ' ' + prefixText);
    this.writeLineBreak();
  }

  writeSingleQuoted(text, split = true) {
    this.writeIndicator("'", true);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split &&
              start !== 0 && end !== text.length) {
            this.writeIndent();
          } else {
            const data = text.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !inSet(ch, LB)) {
          if (text[start] === '\n') this.writeLineBreak();
          for (const br of text.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || inSet(ch, SPACE_LB) || ch === "'") {
        if (start < end) {
          const data = text.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = inSet(ch, LB);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(text, split = true) {
    this.writeIndicator('"', true);
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (ch === null || inSet(ch, '"\\' + NEL + LS + PS + BOM) ||
          !((ch >= '\x20' && ch <= '\x7e') ||
            (this.allowUnicode && isPrintableUnicode(ch)))) {
        if (start < end) {
          const data = text.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else {
            const code = ord(ch);
            if (code <= 0xff) data = '\\x' + hexUpper(code, 2);
            else if (code <= 0xffff) data = '\\u' + hexUpper(code, 4);
            else data = '\\U' + hexUpper(code, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < text.length - 1 && (ch === ' ' || start >= end) &&
          this.column + (end - start) > this.bestWidth && split) {
        let data = text.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += cpLen(data);
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (text[start] === ' ') {
          data = '\\';
          this.column += 1;
          this.write(data);
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false);
  }

  determineBlockHints(text) {
    let hints = '';
    if (text.length > 0) {
      if (inSet(text[0], SPACE_LB)) hints += String(this.bestIndent);
      if (!inSet(text[text.length - 1], LB)) hints += '-';
      else if (text.length === 1 || inSet(text[text.length - 2], LB)) hints += '+';
    }
    return hints;
  }

  writeFolded(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('>' + hints, true);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (breaks) {
        if (ch === null || !inSet(ch, LB)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && text[start] === '\n') {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of text.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = text.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || inSet(ch, SPACE_LB)) {
        const data = text.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = inSet(ch, LB);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true);
    if (hints.slice(-1) === '+') this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (breaks) {
        if (ch === null || !inSet(ch, LB)) {
          for (const br of text.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || inSet(ch, LB)) {
        const data = text.slice(start, end).join('');
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = inSet(ch, LB);
      end += 1;
    }
  }

  writePlain(text, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (text.length === 0) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            const data = text.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (!inSet(ch === null ? '' : ch, LB)) {
          if (text[start] === '\n') this.writeLineBreak();
          for (const br of text.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || inSet(ch, SPACE_LB)) {
        const data = text.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = inSet(ch, LB);
      }
      end += 1;
    }
  }
}

function isPrintableUnicode(ch) {
  const code = ord(ch);
  return (code >= 0xa0 && code <= 0xd7ff) || (code >= 0xe000 && code <= 0xfffd) ||
    (code >= 0x10000 && code < 0x10ffff);
}

/** UTF-8 encoding of a single character, for percent-escaping in tags. */
function utf8Bytes(ch) {
  const code = ord(ch);
  if (code < 0x80) return [code];
  if (code < 0x800) return [0xc0 | (code >> 6), 0x80 | (code & 0x3f)];
  if (code < 0x10000) {
    return [0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f)];
  }
  return [
    0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f),
    0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f),
  ];
}

