// Assigns anchors and turns the node graph into events (yaml/serializer.py).

import { pad } from '../py/chars.mjs';
import { SerializerError } from './error.mjs';
import { Emitter } from './emitter.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';
import {
  AliasEvent, DocumentEndEvent, DocumentStartEvent, MappingEndEvent, MappingStartEvent,
  ScalarEvent, SequenceEndEvent, SequenceStartEvent, StreamEndEvent, StreamStartEvent,
} from './events.mjs';
import { Resolver } from './resolver.mjs';

export class Serializer extends Emitter {
  constructor(options = {}) {
    super(options);
    this.useEncoding = options.encoding === undefined ? null : options.encoding;
    this.useExplicitStart = options.explicitStart === undefined ? null : options.explicitStart;
    this.useExplicitEnd = options.explicitEnd === undefined ? null : options.explicitEnd;
    this.useVersion = options.version === undefined ? null : options.version;
    this.useTags = options.tags === undefined ? null : options.tags;
    this.serializedNodes = new Map();
    this.anchors = new Map();
    this.lastAnchorId = 0;
    this.closed = null;
    const resolver = new Resolver();
    this.resolve = resolver.resolve.bind(resolver);
    this.descendResolver = resolver.descendResolver.bind(resolver);
    this.ascendResolver = resolver.ascendResolver.bind(resolver);
  }

  open() {
    if (this.closed === null) {
      this.emit(new StreamStartEvent(null, null, this.useEncoding));
      this.closed = false;
    } else if (this.closed) {
      throw new SerializerError('serializer is closed');
    } else {
      throw new SerializerError('serializer is already opened');
    }
  }

  close() {
    if (this.closed === null) throw new SerializerError('serializer is not opened');
    if (!this.closed) {
      this.emit(new StreamEndEvent());
      this.closed = true;
    }
  }

  serialize(node) {
    if (this.closed === null) throw new SerializerError('serializer is not opened');
    if (this.closed) throw new SerializerError('serializer is closed');
    this.emit(new DocumentStartEvent(null, null, this.useExplicitStart, this.useVersion, this.useTags));
    this.anchorNode(node);
    this.serializeNode(node, null, null);
    this.emit(new DocumentEndEvent(null, null, this.useExplicitEnd));
    this.serializedNodes = new Map();
    this.anchors = new Map();
    this.lastAnchorId = 0;
  }

  /**
   * Pre-order walk marking shared nodes. A node gets an anchor only when it is
   * reached a second time, so anchor numbering follows the order of the second
   * references, not the first.
   */
  anchorNode(node) {
    if (this.anchors.has(node)) {
      if (this.anchors.get(node) === null) this.anchors.set(node, this.generateAnchor());
      return;
    }
    this.anchors.set(node, null);
    if (node instanceof SequenceNode) {
      for (const item of node.value) this.anchorNode(item);
    } else if (node instanceof MappingNode) {
      for (const [key, value] of node.value) {
        this.anchorNode(key);
        this.anchorNode(value);
      }
    }
  }

  generateAnchor() {
    this.lastAnchorId += 1;
    return 'id' + pad(this.lastAnchorId, 3);
  }

  serializeNode(node, parent, index) {
    const alias = this.anchors.get(node);
    if (this.serializedNodes.has(node)) {
      this.emit(new AliasEvent(alias));
      return;
    }
    this.serializedNodes.set(node, true);
    this.descendResolver(parent, index);
    if (node instanceof ScalarNode) {
      const detectedTag = this.resolve(ScalarNode, node.value, [true, false]);
      const defaultTag = this.resolve(ScalarNode, node.value, [false, true]);
      const implicit = [node.tag === detectedTag, node.tag === defaultTag];
      this.emit(new ScalarEvent(alias, node.tag, implicit, node.value, null, null, node.style));
    } else if (node instanceof SequenceNode) {
      const implicit = node.tag === this.resolve(SequenceNode, node.value, true);
      this.emit(new SequenceStartEvent(alias, node.tag, implicit, null, null, node.flowStyle));
      let at = 0;
      for (const item of node.value) {
        this.serializeNode(item, node, at);
        at += 1;
      }
      this.emit(new SequenceEndEvent());
    } else if (node instanceof MappingNode) {
      const implicit = node.tag === this.resolve(MappingNode, node.value, true);
      this.emit(new MappingStartEvent(alias, node.tag, implicit, null, null, node.flowStyle));
      for (const [key, value] of node.value) {
        this.serializeNode(key, node, null);
        this.serializeNode(value, node, key);
      }
      this.emit(new MappingEndEvent());
    }
    this.ascendResolver();
  }
}

